class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: GetEnvironmentVariable returns null for empty
        // values on non-Windows. Use string.IsNullOrEmpty to detect "set but empty",
        // or call the native API directly. Here we need to distinguish "not set" from
        // "explicitly empty", so we use the raw /proc environ check.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val == null && !IsEnvironmentVariableDefined("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    // .NET 9+: Environment.GetEnvironmentVariable returns null for both unset and
    // empty vars on Linux. To distinguish, check /proc/self/environ directly.
    private static bool IsEnvironmentVariableDefined(string name)
    {
        if (!OperatingSystem.IsLinux()) return Environment.GetEnvironmentVariable(name) != null;
        try
        {
            var environ = File.ReadAllText("/proc/self/environ");
            return environ.Split('\0').Any(e => e == name + "=" || e.StartsWith(name + "="));
        }
        catch
        {
            return false;
        }
    }
}

